import hashlib
import importlib.util
import io
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
import zipfile

from PIL import Image
from pypdf import PdfReader, PdfWriter
from reportlab.pdfgen import canvas

SCRIPT = Path(__file__).resolve().parents[2] / "resources/skills/pdf-workflows/scripts/pdf_tool.py"
# Skill resources are bundled into Rust; never leave generated bytecode there.
sys.dont_write_bytecode = True
spec = importlib.util.spec_from_file_location("pdf_tool", SCRIPT)
tool = importlib.util.module_from_spec(spec)
spec.loader.exec_module(tool)


class PdfToolTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        self.workspace = tool.Workspace(self.root)
        data = io.BytesIO()
        pdf = canvas.Canvas(data, pagesize=(300, 400))
        for label in ("FIRST secret 12345", "SECOND invoice 987", "THIRD appendix"):
            pdf.drawString(30, 300, label)
            pdf.showPage()
        pdf.save()
        (self.root / "input.pdf").write_bytes(data.getvalue())

    def tearDown(self):
        self.workspace.close()
        self.temp.cleanup()

    def run_tool(self, operation, options=None, output="result.pdf", inputs=None):
        request = {"operation": operation, "inputs": inputs or [{"path": "input.pdf"}]}
        if operation != "inspect":
            request["output"] = output
        if options is not None:
            request["options"] = options
        return tool.execute(self.workspace, request)

    def read(self, name="result.pdf"):
        return PdfReader(self.root / name)

    def test_inspect_and_hash_precondition(self):
        result = self.run_tool("inspect")
        self.assertEqual(result["page_count"], 3)
        self.assertEqual(result["pages"][0]["width"], 300)
        digest = result["inputs"][0]["sha256"]
        self.run_tool("assemble", inputs=[{"path": "input.pdf", "sha256": digest, "pages": [3, 1, 1]}])
        self.assertEqual([p.extract_text().split()[0] for p in self.read().pages], ["THIRD", "FIRST", "FIRST"])
        with self.assertRaisesRegex(ValueError, "SHA-256"):
            self.run_tool("assemble", output="changed.pdf", inputs=[{"path": "input.pdf", "sha256": "0" * 64}])
        self.assertFalse((self.root / "changed.pdf").exists())

    def test_merge_and_split_preserve_order(self):
        self.run_tool("assemble", inputs=[{"path": "input.pdf", "pages": [2]}, {"path": "input.pdf", "pages": [1]}])
        self.assertEqual([p.extract_text().split()[0] for p in self.read().pages], ["SECOND", "FIRST"])
        self.run_tool("split", {"pages": [3, 1]}, output="split.zip")
        with zipfile.ZipFile(self.root / "split.zip") as archive:
            self.assertEqual(archive.namelist(), ["0001-page-3.pdf", "0002-page-1.pdf"])
            self.assertIn("THIRD", PdfReader(io.BytesIO(archive.read(archive.namelist()[0]))).pages[0].extract_text())

    def test_rotate_and_crop_do_not_redact(self):
        self.run_tool("rotate", {"pages": [2], "degrees": 90})
        self.assertEqual([p.rotation for p in self.read().pages], [0, 90, 0])
        self.run_tool("crop", {"pages": [1], "box": [.2, .2, .8, .8]}, output="crop.pdf")
        page = self.read("crop.pdf").pages[0]
        self.assertAlmostEqual(float(page.cropbox.width), 180)
        self.assertIn("secret", page.extract_text())

    def test_unicode_watermark_and_numbering(self):
        self.run_tool("watermark", {"text": "REVISIÓN Ñ", "pages": [2]})
        self.assertIn("REVISIÓN Ñ", self.read().pages[1].extract_text())
        self.assertNotIn("REVISIÓN", self.read().pages[0].extract_text())
        self.run_tool("number", {"start": 42}, output="numbered.pdf")
        self.assertIn("42", self.read("numbered.pdf").pages[0].extract_text())
        self.assertIn("44", self.read("numbered.pdf").pages[2].extract_text())

    def test_metadata_and_lossless_compression(self):
        self.run_tool("metadata", {"values": {"Title": "Own report"}})
        self.assertEqual(self.read().metadata.title, "Own report")
        self.run_tool("compress", output="compressed.pdf")
        self.assertEqual([p.extract_text() for p in self.read("compressed.pdf").pages],
                         [p.extract_text() for p in self.read("input.pdf").pages])

    def test_text_form_fill_and_unknown_field(self):
        data = io.BytesIO()
        pdf = canvas.Canvas(data, pagesize=(300, 400))
        pdf.acroForm.textfield(name="customer", x=10, y=250, width=200, height=25)
        pdf.showPage()
        pdf.save()
        (self.root / "form.pdf").write_bytes(data.getvalue())
        self.run_tool("fill", {"fields": {"customer": "Ana"}}, inputs=[{"path": "form.pdf"}])
        self.assertEqual(self.read().get_form_text_fields()["customer"], "Ana")
        with self.assertRaisesRegex(ValueError, "Unknown field"):
            self.run_tool("fill", {"fields": {"absent": "Ana"}}, output="bad.pdf", inputs=[{"path": "form.pdf"}])

    def test_render_and_images_round_trip(self):
        self.run_tool("render", {"pages": [2], "dpi": 72}, output="pages.zip")
        with zipfile.ZipFile(self.root / "pages.zip") as archive:
            data = archive.read("0001-page-2.png")
        (self.root / "page.png").write_bytes(data)
        with Image.open(io.BytesIO(data)) as bitmap:
            self.assertEqual(bitmap.size, (300, 400))
        self.run_tool("images", {"dpi": 72}, inputs=[{"path": "page.png"}])
        self.assertEqual(len(self.read().pages), 1)
        self.assertEqual(float(self.read().pages[0].mediabox.width), 300)

    def test_redaction_removes_original_objects_and_blacks_pixels(self):
        # Include invisible text, an attachment and an action: none may survive reconstruction.
        writer = PdfWriter(clone_from=self.root / "input.pdf")
        writer.add_attachment("secret.txt", b"TOP SECRET")
        writer.add_js("app.alert('untrusted')")
        writer.write(self.root / "active.pdf")
        result = self.run_tool("redact", {"rectangles": {"1": [[0, 0, 1, .5]]}, "dpi": 72},
                               inputs=[{"path": "active.pdf"}])
        pdf = self.read()
        self.assertEqual(len(pdf.pages), 3)
        self.assertFalse(pdf.attachments)
        self.assertFalse(pdf.get_fields())
        self.assertNotIn("/Names", pdf.trailer["/Root"])
        self.assertTrue(all(not p.extract_text() for p in pdf.pages))
        self.assertIn("image-only", result["verification"])
        image = next(tool.render((self.root / "result.pdf").read_bytes(), [0], 72))[2]
        self.assertEqual(image.getpixel((100, 100)), (0, 0, 0))
        self.assertEqual(image.getpixel((100, 300)), (255, 255, 255))
        image.close()

    def test_raster_grayscale(self):
        self.run_tool("rasterize", {"pages": [2], "grayscale": True, "dpi": 72})
        self.assertEqual(len(self.read().pages), 1)
        self.assertFalse(self.read().pages[0].extract_text())

    def test_paths_symlinks_hardlinks_and_no_overwrite(self):
        for path in ("../input.pdf", "/etc/passwd", "https://example.com/x.pdf"):
            with self.subTest(path=path), self.assertRaises(ValueError):
                self.workspace.read(path)
        (self.root / "link.pdf").symlink_to(self.root / "input.pdf")
        with self.assertRaises(OSError):
            self.workspace.read("link.pdf")
        (self.root / "dir").symlink_to(self.root, target_is_directory=True)
        with self.assertRaises(OSError):
            self.workspace.publish("dir/out.pdf", b"x")
        before = (self.root / "input.pdf").read_bytes()
        with self.assertRaises(ValueError):
            self.run_tool("compress", output="input.pdf")
        with self.assertRaises(FileExistsError):
            self.workspace.publish("link.pdf", b"changed")
        self.assertEqual(before, (self.root / "input.pdf").read_bytes())
        (self.root / "hard.pdf").hardlink_to(self.root / "input.pdf")
        with self.assertRaises(ValueError):
            self.workspace.read("hard.pdf")

    def test_invalid_options_pages_and_rectangles(self):
        for operation, options in [("rotate", {"degrees": 45}), ("rotate", {"degrees": 90, "pages": [True]}),
                                   ("crop", {"box": [0, 0, 2, 1]}), ("number", {"start": 1, "unknown": True}),
                                   ("redact", {"rectangles": {"99": [[0, 0, 1, 1]]}})]:
            with self.subTest(operation=operation), self.assertRaises(ValueError):
                self.run_tool(operation, options)
        self.assertFalse((self.root / "result.pdf").exists())

    def test_corruption_encryption_and_raster_limits(self):
        (self.root / "broken.pdf").write_bytes(b"%PDF-1.4 broken")
        with self.assertRaises(Exception):
            self.run_tool("inspect", inputs=[{"path": "broken.pdf"}])
        writer = PdfWriter(clone_from=self.root / "input.pdf")
        writer.encrypt("secret")
        writer.write(self.root / "encrypted.pdf")
        with self.assertRaisesRegex(ValueError, "Encrypted"):
            self.run_tool("inspect", inputs=[{"path": "encrypted.pdf"}])
        huge = PdfWriter()
        huge.add_blank_page(width=10000, height=10000)
        huge.write(self.root / "huge.pdf")
        with self.assertRaisesRegex(ValueError, "pixels"):
            self.run_tool("render", {"pages": [1]}, output="huge.zip", inputs=[{"path": "huge.pdf"}])
        self.assertFalse((self.root / "huge.zip").exists())

    def test_cli_receipt_and_failure(self):
        request = {"operation": "rotate", "inputs": [{"path": "input.pdf"}], "options": {"degrees": 90}, "output": "cli.pdf"}
        (self.root / "request.json").write_text(json.dumps(request))
        cmd = [sys.executable, "-I", str(SCRIPT), "--workspace", str(self.root), "--request", "request.json"]
        result = subprocess.run(cmd, capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stderr + result.stdout)
        receipt = json.loads(result.stdout)
        self.assertEqual(receipt["output"]["sha256"], hashlib.sha256((self.root / "cli.pdf").read_bytes()).hexdigest())
        again = subprocess.run(cmd, capture_output=True, text=True)
        self.assertEqual(again.returncode, 1)
        self.assertEqual(json.loads(again.stdout)["status"], "failed")


if __name__ == "__main__":
    unittest.main()
